  surface_index: u32,
  material_id: f32,
  phase_id: f32,
  triangle_index: u32,
  vertex_index: u32,
  position: vec3<f32>,
  normal: vec3<f32>,
  optical_state_id: f32,
  density: f32,
  isolation: f32,
