  let residuals_admitted = mass_residual <= mass_tolerance
    && max(first_residual.x, max(first_residual.y, first_residual.z)) <= first_tolerance
    && max(momentum_residual.x, max(momentum_residual.y, momentum_residual.z))
      <= momentum_tolerance
